const WEIGHTS = [8, 6, 4, 2, 3, 5, 9, 7];

/** UPU S10 check digit for 8 serial digits (see docs/carriers.md). */
export function s10CheckDigit(serial: string): number {
  let sum = 0;
  for (let i = 0; i < 8; i++) sum += Number(serial[i]) * WEIGHTS[i]!;
  const result = 11 - (sum % 11);
  if (result === 10) return 0;
  if (result === 11) return 5;
  return result;
}

const S10_AT = /^[A-Z]{2}(\d{8})(\d)AT$/;

export type S10Problem = 'format' | 'check_digit';

/** Checks an Austrian Post S10 number (expects upper case). Returns null if valid. */
export function checkAtpTrackingNumber(trackingNumber: string): S10Problem | null {
  const match = S10_AT.exec(trackingNumber);
  if (!match) return 'format';
  return s10CheckDigit(match[1]!) === Number(match[2]) ? null : 'check_digit';
}
